contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will first deposit `amount` into c for this contract, then attempt withdraw.
    // Parameters: amount to deposit. The function is payable so the test harness can fund this contract.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Ensure we start with some recorded balance by calling addToBalance.
        // Capture balances before withdraw attempt.
        bool depositReverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depositReverted = true;
        } else {
            depositReverted = false;
        }

        // read before-values
        uint256 beforeUserBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractBalance = address(c).balance;

        // Attempt withdraw and record whether it reverted
        bool withdrawReverted;
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // read after-values
        uint256 afterUserBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractBalance = address(c).balance;

        // If withdraw did not revert, then the recorded user balance must be zero and the contract's balance must not have increased.
        // We allow that deposit might have reverted; the rule is conditional on withdraw success only.
        assert(withdrawReverted || (afterUserBalance == 0 && afterContractBalance <= beforeContractBalance));
    }

    // allow receiving Ether so the test contract can fund calls and receive withdrawn Ether
    receive() external payable {}
}

